function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  // tree trunk
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2, H/2 - 50 * (1 + Math.sin(t)));
  ctx.stroke();
  // tree branches
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 50 * (1 + Math.sin(t)));
  ctx.lineTo(W/2 - 20 * Math.cos(t), H/2 - 80 * (1 + Math.sin(t)));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 50 * (1 + Math.sin(t)));
  ctx.lineTo(W/2 + 20 * Math.cos(t), H/2 - 80 * (1 + Math.sin(t)));
  ctx.stroke();
  // leaves
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.arc(W/2 - 20 * Math.cos(t), H/2 - 80 * (1 + Math.sin(t)), 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 20 * Math.cos(t), H/2 - 80 * (1 + Math.sin(t)), 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.restore();
}
